import java.nio.file.*;import java.util.*;import io.ivo.engine.*;
public class MeasureOnce { public static void main(String[] a)throws Exception { byte[] in=Files.readAllBytes(Path.of(a[0])); for(int i=0;i<1;i++){long t=System.nanoTime();var r=new Router(a.length>2?Router.Mode.valueOf(a[2]):Router.Mode.AUTO).compress(in,"27667.jpg");double ms=(System.nanoTime()-t)/1e6; if(!Arrays.equals(in,new Router().decompress(r.bytes())))throw new AssertionError();System.out.println("run="+i+" ms="+ms+" size="+r.bytes().length);for(var x:r.results())System.out.println(x);Files.write(Path.of(a[1]),r.bytes());}}}
